# Debug: process each value separately and verify

def apply_one(input_grid, r, c, val):
    h, w = len(input_grid), len(input_grid[0])
    result = [[x for x in row] for row in input_grid]

    if val % 2 == 1:  # ODD
        dist_up, dist_down = r, h-1-r
        nr = max(0, r-val) if dist_up <= dist_down else min(h-1, r+val)

        result[r][c] = val
        result[nr][c] = val

        if nr < r:
            for rr in range(r-1, nr, -1):
                result[rr][c] = 5
        else:
            for rr in range(r+1, nr):
                result[rr][c] = 5

        spread = min(val*2, w-c-1)
        for j in range(c+1, c+spread+1):
            result[r][j] = 5

    else:  # EVEN
        space_left = c
        space_right = w-1-c
        should_go_left = (space_left >= val) and (space_left >= space_right)

        if should_go_left:
            nc = c - val
            dc = val
            result[r][c] = val
            result[r][nc] = val
            for cc in range(c-1, nc, -1):
                result[r][cc] = 5
            diag_r, diag_c = r+1, nc+1
            while diag_r < h and diag_c >= 0:
                result[diag_r][diag_c] = dc
                diag_r += 1
                diag_c -= 1
        else:
            # VERTICAL - NO DIAGONALS
            dist_up, dist_down = r, h-1-r
            nr = max(0, r-val) if dist_up <= dist_down else min(h-1, r+val)

            result[r][c] = val
            result[nr][c] = val

            if nr < r:
                for rr in range(r-1, nr, -1):
                    result[rr][c] = 5
            else:
                for rr in range(r+1, nr):
                    result[rr][c] = 5

    return result

